/**
 * Policy Clauses — Device & Media (p23–p25)
 * ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, NIS2 Art.21
 */
import type { PolicyClause } from "../policyClauseTemplates";

// ═══════════════════════════════════════════════════════════════
// P23 — Mobile Device Management (MDM) Policy (22 clauses)
// ═══════════════════════════════════════════════════════════════
const p23: PolicyClause[] = [
  { id: "p23-c00", title: "MDM-Strategie und Geltungsbereich", titleEn: "MDM Strategy and Scope", description: "Wir müssen eine umfassende Mobile Device Management-Strategie definieren, die alle mobilen Gerätetypen abdeckt: Smartphones, Tablets, Laptops und Wearables. Die Strategie muss sowohl firmeneigene Geräte (COPE — Corporate-Owned Personally Enabled) als auch BYOD-Geräte berücksichtigen. Für jeden Gerätetyp und jedes Eigentumsmodell müssen spezifische Sicherheitsanforderungen definiert werden.", descriptionEn: "We must define a comprehensive Mobile Device Management strategy covering all mobile device types: smartphones, tablets, laptops, and wearables. The strategy must address both corporate-owned devices (COPE) and BYOD devices. Specific security requirements must be defined for each device type and ownership model.", reason: "Ohne klare MDM-Strategie fehlt die Grundlage für konsistenten Schutz der wachsenden mobilen Geräteflotte.", reasonEn: "Without a clear MDM strategy, the foundation for consistent protection of the growing mobile device fleet is missing.", whenRequired: "Immer erforderlich bei mobiler Gerätenutzung.", whenRequiredEn: "Always required when using mobile devices.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "NIST CSF 2.0 PR.PS", "CIS Controls v8 1.2"] },
  { id: "p23-c01", title: "Geräte-Enrollment und Registrierung", titleEn: "Device Enrolment and Registration", description: "Alle mobilen Geräte müssen vor dem Zugriff auf Organisationsressourcen im MDM-System registriert werden. Das Enrollment muss eine Identitätsverifikation des Benutzers, die Installation des MDM-Profils und die Anwendung der Sicherheitsbaseline umfassen. Nicht registrierte Geräte dürfen keinen Zugang zu Organisationsdaten erhalten.", descriptionEn: "All mobile devices must be registered in the MDM system before accessing organisational resources. Enrolment must include user identity verification, MDM profile installation, and security baseline application. Unregistered devices must not gain access to organisational data.", reason: "Ohne Enrollment-Pflicht können unkontrollierte Geräte auf sensible Daten zugreifen.", reasonEn: "Without enrolment requirement, uncontrolled devices can access sensitive data.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 1.4"] },
  { id: "p23-c02", title: "Mobilgerätespezifische Verschlüsselung", titleEn: "Mobile-Device-Specific Encryption", description: "Alle verwalteten mobilen Geräte müssen vollständig verschlüsselt sein — Gerätespeicher und externe Speicherkarten. Die Verschlüsselung muss hardwarebasiert sein (wo unterstützt) und vom MDM-System erzwungen werden. Geräte ohne aktive Verschlüsselung müssen automatisch gesperrt oder ihre Organisationsdaten gelöscht werden. Die allgemeinen Verschlüsselungsstandards und kryptographischen Vorgaben (Algorithmen, Schlüssellängen, Schlüsselmanagement) werden in p17 (Endpoint Security) definiert; diese Klausel regelt die mobilgerätespezifische Durchsetzung über MDM.", descriptionEn: "All managed mobile devices must be fully encrypted — device storage and external storage cards. Encryption must be hardware-based (where supported) and enforced by the MDM system. Devices without active encryption must be automatically locked or have their organisational data wiped. General encryption standards and cryptographic requirements (algorithms, key lengths, key management) are defined in p17 (Endpoint Security); this clause governs mobile-device-specific enforcement via MDM.", reason: "Mobile Geräte gehen häufiger verloren oder werden gestohlen als stationäre Geräte; Verschlüsselung schützt die Daten in diesen Fällen.", reasonEn: "Mobile devices are more frequently lost or stolen than stationary devices; encryption protects data in these cases.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.24", "BSI IT-Grundschutz SYS.3.2.1", "NIS2 Art.21(2)(e)"] },
  { id: "p23-c03", title: "Bildschirmsperre und Authentifizierung", titleEn: "Screen Lock and Authentication", description: "Alle verwalteten Geräte müssen eine Bildschirmsperre mit starkem Passcode (mindestens 6-stellige PIN oder Muster) oder biometrischer Authentifizierung haben. Automatische Sperre nach maximal 5 Minuten Inaktivität muss erzwungen werden. Nach 10 fehlgeschlagenen Entsperrversuchen muss das Gerät automatisch gelöscht oder gesperrt werden.", descriptionEn: "All managed devices must have a screen lock with strong passcode (minimum 6-digit PIN or pattern) or biometric authentication. Automatic lock after maximum 5 minutes of inactivity must be enforced. After 10 failed unlock attempts, the device must be automatically wiped or locked.", reason: "Ohne Bildschirmsperre sind alle Daten auf einem verlorenen oder unbeaufsichtigten Gerät sofort zugänglich.", reasonEn: "Without screen lock, all data on a lost or unattended device is immediately accessible.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 4.3"] },
  { id: "p23-c04", title: "Remote-Löschung (Remote Wipe)", titleEn: "Remote Wipe", description: "Das MDM-System muss die Fähigkeit zur Remote-Löschung aller Geräte bieten — vollständige Löschung (bei firmeneigenen Geräten) und selektive Löschung von Organisationsdaten (bei BYOD). Remote Wipe muss innerhalb von 24 Stunden nach Meldung eines Verlusts/Diebstahls ausgelöst werden. Der Prozess muss dokumentiert und getestet sein.", descriptionEn: "The MDM system must provide remote wipe capability for all devices — full wipe (for corporate-owned devices) and selective wipe of organisational data (for BYOD). Remote wipe must be triggered within 24 hours of loss/theft report. The process must be documented and tested.", reason: "Bei Verlust oder Diebstahl ist Remote Wipe die letzte Verteidigungslinie gegen Datenverlust.", reasonEn: "In case of loss or theft, remote wipe is the last line of defence against data loss.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 1.2"] },
  { id: "p23-c05", title: "App-Management und Whitelisting", titleEn: "App Management and Whitelisting", description: "Die Installation von Apps auf verwalteten Geräten muss kontrolliert werden. Ein Unternehmens-App-Store muss genehmigte Apps bereitstellen. Die Installation aus unbekannten Quellen (Sideloading) muss blockiert werden. Blacklisting bekannter riskanter Apps muss implementiert werden. App-Berechtigungen müssen überwacht werden.", descriptionEn: "App installation on managed devices must be controlled. An enterprise app store must provide approved apps. Installation from unknown sources (sideloading) must be blocked. Blacklisting of known risky apps must be implemented. App permissions must be monitored.", reason: "Unkontrollierte App-Installation kann Malware, Datenlecks und Compliance-Verstöße verursachen.", reasonEn: "Uncontrolled app installation can cause malware, data leaks, and compliance violations.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.19", "BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 2.5"] },
  { id: "p23-c06", title: "Containerisierung und Datentrennung", titleEn: "Containerisation and Data Separation", description: "Organisationsdaten auf mobilen Geräten müssen in einem verschlüsselten Container getrennt von persönlichen Daten gespeichert werden. Der Container muss verhindern, dass Organisationsdaten in persönliche Apps kopiert werden (DLP — Data Loss Prevention). Bei BYOD ist Containerisierung obligatorisch.", descriptionEn: "Organisational data on mobile devices must be stored in an encrypted container separated from personal data. The container must prevent organisational data from being copied to personal apps (DLP). For BYOD, containerisation is mandatory.", reason: "Datentrennung schützt sowohl Organisationsdaten als auch die Privatsphäre der Mitarbeiter.", reasonEn: "Data separation protects both organisational data and employee privacy.", whenRequired: "Erforderlich, insbesondere bei BYOD.", whenRequiredEn: "Required, especially for BYOD.", sources: ["ISO 27001:2022 A.8.12", "BSI IT-Grundschutz SYS.3.2.1", "DSGVO Art.5"] },
  { id: "p23-c07", title: "MDM-gesteuerte OS-Mindestversion und Update-Compliance", titleEn: "MDM-Controlled Minimum OS Version and Update Compliance", description: "Für verwaltete mobile Geräte muss eine Mindest-Betriebssystemversion definiert werden, die aktiv Sicherheitsupdates erhält. Geräte unter der Mindestversion müssen automatisch gesperrt oder auf Organisationsdaten beschränkt werden. Die Mindestversion muss bei jeder neuen OS-Version aktualisiert werden. Die Patch-Verteilung für stationäre Remote-Arbeitsplätze wird in p22-c16 geregelt; diese Klausel fokussiert auf die MDM-spezifische OS-Version-Compliance für Smartphones, Tablets und Wearables.", descriptionEn: "A minimum operating system version actively receiving security updates must be defined for managed mobile devices. Devices below the minimum version must be automatically locked or restricted from organisational data. The minimum version must be updated with each new OS release. Patch distribution for stationary remote workstations is governed in p22-c16; this clause focuses on MDM-specific OS version compliance for smartphones, tablets, and wearables.", reason: "Veraltete mobile Betriebssysteme haben bekannte, nicht behebbare Sicherheitslücken.", reasonEn: "Outdated mobile operating systems have known, unfixable security vulnerabilities.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 2.2"] },
  { id: "p23-c08", title: "Jailbreak-/Root-Erkennung", titleEn: "Jailbreak/Root Detection", description: "Das MDM-System muss Jailbreak (iOS) und Root-Zugang (Android) auf verwalteten Geräten erkennen. Erkannte Geräte müssen sofort den Zugriff auf Organisationsressourcen verlieren und das Sicherheitsteam muss benachrichtigt werden. Regelmäßige Compliance-Checks müssen den Geräte-Integritätsstatus überprüfen.", descriptionEn: "The MDM system must detect jailbreak (iOS) and root access (Android) on managed devices. Detected devices must immediately lose access to organisational resources and the security team must be notified. Regular compliance checks must verify device integrity status.", reason: "Jailbreak/Root entfernt grundlegende Sicherheitsmechanismen des Betriebssystems und macht das Gerät anfällig für Malware.", reasonEn: "Jailbreak/root removes fundamental operating system security mechanisms and makes the device vulnerable to malware.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1"] },
  { id: "p23-c09", title: "Sichere WLAN-Konfiguration für mobile Geräte", titleEn: "Secure Wi-Fi Configuration for Mobile Devices", description: "Das MDM muss WLAN-Profile zentral verteilen und konfigurieren. Automatische Verbindung zu unbekannten oder offenen WLANs muss deaktiviert werden. Zertifikatsbasierte WLAN-Authentifizierung muss für Unternehmensnetzwerke verwendet werden. VPN-Auto-Connect für nicht vertrauenswürdige Netzwerke muss aktiviert sein. Die unternehmensweite WLAN-Architektur, Segmentierung und Netzwerkzugangskontrolle (NAC) wird in p16 (Netzwerksicherheit) geregelt; diese Klausel fokussiert auf die MDM-seitige Profilverteilung und gerätespezifische WLAN-Einschränkungen.", descriptionEn: "The MDM must centrally distribute and configure Wi-Fi profiles. Automatic connection to unknown or open Wi-Fi networks must be disabled. Certificate-based Wi-Fi authentication must be used for corporate networks. VPN auto-connect for untrusted networks must be enabled. Enterprise-wide Wi-Fi architecture, segmentation, and network access control (NAC) is governed in p16 (Network Security); this clause focuses on MDM-side profile distribution and device-specific Wi-Fi restrictions.", reason: "Unsichere WLAN-Verbindungen auf mobilen Geräten ermöglichen Man-in-the-Middle-Angriffe und Datenabfang.", reasonEn: "Insecure Wi-Fi connections on mobile devices enable man-in-the-middle attacks and data interception.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 12.6"] },
  { id: "p23-c10", title: "E-Mail-Sicherheit auf mobilen Geräten", titleEn: "Email Security on Mobile Devices", description: "Organisatorische E-Mails auf mobilen Geräten müssen über verwaltete E-Mail-Clients innerhalb des Containers abgerufen werden. E-Mail-Anhänge müssen im Container verbleiben (Öffnung nur in verwalteten Apps). ActiveSync-Richtlinien müssen Verschlüsselung, Passcode und Remote Wipe erzwingen.", descriptionEn: "Organisational emails on mobile devices must be accessed through managed email clients within the container. Email attachments must remain in the container (opening only in managed apps). ActiveSync policies must enforce encryption, passcode, and remote wipe.", reason: "E-Mails enthalten häufig vertrauliche Informationen, die auf mobilen Geräten besonders geschützt werden müssen.", reasonEn: "Emails frequently contain confidential information that must be especially protected on mobile devices.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.12", "BSI IT-Grundschutz SYS.3.2.1"] },
  { id: "p23-c11", title: "Mobile Threat Defence (MTD)", titleEn: "Mobile Threat Defence (MTD)", description: "Auf verwalteten mobilen Geräten muss eine Mobile Threat Defence-Lösung installiert sein, die vor Netzwerkangriffen, bösartigen Apps, Phishing-Links und Betriebssystem-Schwachstellen schützt. MTD-Alarme müssen an das SOC weitergeleitet werden. Die MTD-Lösung muss in das MDM integriert sein.", descriptionEn: "A Mobile Threat Defence solution must be installed on managed mobile devices protecting against network attacks, malicious apps, phishing links, and operating system vulnerabilities. MTD alerts must be forwarded to the SOC. The MTD solution must be integrated into the MDM.", reason: "Mobile Geräte sind zunehmend Ziel von fortgeschrittenen Angriffen, die Standard-MDM-Kontrollen umgehen.", reasonEn: "Mobile devices are increasingly targeted by advanced attacks that bypass standard MDM controls.", whenRequired: "Empfohlen für alle, erforderlich für Führungskräfte und Hochrisiko-Benutzer.", whenRequiredEn: "Recommended for all, required for executives and high-risk users.", sources: ["BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 10.5", "NIST CSF 2.0 DE.CM-01"] },
  { id: "p23-c12", title: "Verlust- und Diebstahlmeldeprozess", titleEn: "Loss and Theft Reporting Process", description: "Es muss ein klar definierter Prozess für die Meldung verlorener oder gestohlener Geräte existieren. Benutzer müssen den Verlust innerhalb von 4 Stunden melden. Nach Meldung muss das Gerät sofort gesperrt, geortet (wo zulässig) und gelöscht werden. Der Prozess muss außerhalb der Geschäftszeiten verfügbar sein (Notrufnummer, Self-Service-Portal).", descriptionEn: "A clearly defined process for reporting lost or stolen devices must exist. Users must report loss within 4 hours. After reporting, the device must be immediately locked, located (where permitted), and wiped. The process must be available outside business hours (emergency number, self-service portal).", reason: "Jede Stunde Verzögerung bei der Meldung erhöht das Risiko eines Datenzugriffs durch unbefugte Dritte.", reasonEn: "Every hour of delay in reporting increases the risk of data access by unauthorised third parties.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.9", "BSI IT-Grundschutz SYS.3.2.1"] },
  { id: "p23-c13", title: "USB-/Debugging-/Entwicklermodus-Einschränkungen", titleEn: "USB/Debugging/Developer Mode Restrictions", description: "USB-Debugging, Entwicklermodus und ADB-Zugang müssen auf verwalteten Geräten deaktiviert werden. USB-Datentransfer auf firmeneigenen Geräten muss auf genehmigtes Zubehör beschränkt werden. Diese Einstellungen müssen über das MDM erzwungen und regelmäßig verifiziert werden.", descriptionEn: "USB debugging, developer mode, and ADB access must be disabled on managed devices. USB data transfer on corporate-owned devices must be restricted to approved accessories. These settings must be enforced via MDM and regularly verified.", reason: "Debugging-Schnittstellen ermöglichen Datenexfiltration und umgehen Sicherheitskontrollen.", reasonEn: "Debugging interfaces enable data exfiltration and bypass security controls.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 4.8"] },
  { id: "p23-c14", title: "Geräte-Compliance-Überprüfung", titleEn: "Device Compliance Verification", description: "Das MDM-System muss den Compliance-Status jedes Geräts kontinuierlich überprüfen: Verschlüsselung aktiv, OS-Version aktuell, kein Jailbreak/Root, MDM-Profil intakt, Passcode aktiv, MTD installiert. Nicht-konforme Geräte müssen automatisch den Zugang zu Organisationsressourcen verlieren.", descriptionEn: "The MDM system must continuously verify the compliance status of each device: encryption active, OS version current, no jailbreak/root, MDM profile intact, passcode active, MTD installed. Non-compliant devices must automatically lose access to organisational resources.", reason: "Ohne kontinuierliche Compliance-Prüfung können Geräte im Laufe der Zeit nicht-konform werden, ohne dass dies bemerkt wird.", reasonEn: "Without continuous compliance checking, devices can become non-compliant over time without being noticed.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "CIS Controls v8 1.3"] },
  { id: "p23-c15", title: "VPN-Nutzung auf mobilen Geräten", titleEn: "VPN Usage on Mobile Devices", description: "Zugriff auf interne Organisationsressourcen von mobilen Geräten muss über VPN oder ZTNA-Lösungen erfolgen. Per-App-VPN sollte implementiert werden, um nur Organisations-Apps durch den VPN-Tunnel zu leiten. Always-On-VPN muss für Geräte mit Zugang zu kritischen Daten konfiguriert werden.", descriptionEn: "Access to internal organisational resources from mobile devices must be conducted via VPN or ZTNA solutions. Per-app VPN should be implemented to route only organisational apps through the VPN tunnel. Always-on VPN must be configured for devices accessing critical data.", reason: "Ohne VPN/ZTNA sind Daten auf dem Transportweg zwischen mobilem Gerät und Organisationsnetzwerk gefährdet.", reasonEn: "Without VPN/ZTNA, data in transit between mobile device and organisational network is at risk.", whenRequired: "Erforderlich bei Zugriff auf interne Ressourcen.", whenRequiredEn: "Required when accessing internal resources.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz SYS.3.2.1", "NIST CSF 2.0 PR.DS-02"] },
  { id: "p23-c16", title: "Geräte-Rückgabe und Außerbetriebnahme", titleEn: "Device Return and Decommissioning", description: "Bei Rückgabe, Austausch oder Außerbetriebnahme mobiler Geräte müssen alle Organisationsdaten sicher gelöscht werden. Das MDM-Profil muss entfernt und das Gerät auf Werkseinstellungen zurückgesetzt werden. Der Löschvorgang muss dokumentiert werden. Leasing-Geräte müssen vor der Rückgabe verifiziert gelöscht werden.", descriptionEn: "During return, replacement, or decommissioning of mobile devices, all organisational data must be securely deleted. The MDM profile must be removed and the device factory reset. The deletion process must be documented. Leased devices must be verifiably wiped before return.", reason: "Unzureichend gelöschte Geräte können vertrauliche Daten an Dritte weitergeben.", reasonEn: "Insufficiently wiped devices can pass confidential data to third parties.", whenRequired: "Immer bei Geräte-Außerbetriebnahme.", whenRequiredEn: "Always during device decommissioning.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz SYS.3.2.1", "NIST SP 800-88"] },
  { id: "p23-c17", title: "Cloud-Backup-Kontrolle für mobile Geräte", titleEn: "Cloud Backup Control for Mobile Devices", description: "Automatische Cloud-Backups (iCloud, Google Drive) müssen für Organisationsdaten kontrolliert werden. Auf firmeneigenen Geräten muss das Backup von Organisationsdaten auf genehmigte Dienste beschränkt werden. Bei BYOD müssen Container-Daten vom persönlichen Backup ausgeschlossen werden.", descriptionEn: "Automatic cloud backups (iCloud, Google Drive) must be controlled for organisational data. On corporate-owned devices, backup of organisational data must be restricted to approved services. For BYOD, container data must be excluded from personal backup.", reason: "Unkontrollierte Cloud-Backups können Organisationsdaten in nicht autorisierte Cloud-Dienste übertragen.", reasonEn: "Uncontrolled cloud backups can transfer organisational data to unauthorised cloud services.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.13", "BSI IT-Grundschutz SYS.3.2.1", "DSGVO Art.28"] },
  { id: "p23-c18", title: "Reise-Sicherheit für mobile Geräte", titleEn: "Travel Security for Mobile Devices", description: "Für Auslandsreisen mit mobilen Geräten müssen spezifische Sicherheitsmaßnahmen gelten: Verwendung von Reise-Geräten mit minimalen Daten, verstärkte Verschlüsselung, VPN-Pflicht, Deaktivierung von Bluetooth und NFC in Hochrisikoländern, keine Nutzung öffentlicher Ladestationen (Juice Jacking), und spezifische Briefings für Reisen in Hochrisikoländer.", descriptionEn: "Specific security measures must apply for international travel with mobile devices: use of travel devices with minimal data, enhanced encryption, VPN mandatory, Bluetooth and NFC disabled in high-risk countries, no use of public charging stations (juice jacking), and specific briefings for travel to high-risk countries.", reason: "Reisende mit mobilen Geräten sind verstärkten Risiken ausgesetzt — Grenzkontrollen, physischer Diebstahl, Spionage.", reasonEn: "Travellers with mobile devices face increased risks — border controls, physical theft, espionage.", whenRequired: "Erforderlich bei Auslandsreisen.", whenRequiredEn: "Required for international travel.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz INF.9"] },
  { id: "p23-c19", title: "Bluetooth- und NFC-Sicherheit", titleEn: "Bluetooth and NFC Security", description: "Bluetooth muss auf verwalteten Geräten so konfiguriert werden, dass die Sichtbarkeit standardmäßig deaktiviert ist und nur genehmigte Geräte-Pairings erlaubt sind. NFC muss kontrolliert werden. Die Nutzung von Bluetooth zum Datenaustausch muss eingeschränkt werden. Bluetooth-Schwachstellen müssen durch aktuelle Firmware-Updates adressiert werden.", descriptionEn: "Bluetooth on managed devices must be configured with visibility disabled by default and only approved device pairings allowed. NFC must be controlled. Use of Bluetooth for data exchange must be restricted. Bluetooth vulnerabilities must be addressed through current firmware updates.", reason: "Bluetooth-Schwachstellen (BlueBorne, BLESA) ermöglichen Angriffe aus kurzer Distanz ohne Benutzerinteraktion.", reasonEn: "Bluetooth vulnerabilities (BlueBorne, BLESA) enable attacks from short distance without user interaction.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 12.6"] },
  { id: "p23-c20", title: "MDM-Reporting und KPIs", titleEn: "MDM Reporting and KPIs", description: "Wir müssen MDM-KPIs definieren und monatlich berichten: Gesamtzahl verwalteter Geräte, Compliance-Rate, Geräte mit veraltetem OS, Jailbreak-/Root-Erkennungen, Remote-Wipe-Vorfälle, MTD-Alarme, Enrollment-Rate neuer Geräte. Ein Dashboard muss der IT-Sicherheitsleitung zur Verfügung stehen.", descriptionEn: "We must define MDM KPIs and report monthly: total managed devices, compliance rate, devices with outdated OS, jailbreak/root detections, remote wipe incidents, MTD alerts, enrolment rate of new devices. A dashboard must be available to IT security management.", reason: "Ohne KPIs ist die Effektivität des MDM-Programms nicht bewertbar.", reasonEn: "Without KPIs, the effectiveness of the MDM programme cannot be assessed.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "NIST CSF 2.0 ID.IM"] },
  { id: "p23-c21", title: "Wearable-Geräte-Sicherheit", titleEn: "Wearable Device Security", description: "Wearables (Smartwatches, Fitness-Tracker) mit Organisationszugang müssen durch die MDM-Richtlinie abgedeckt werden. Sprachassistenten müssen in Sicherheitsbereichen deaktiviert werden. Wearables dürfen keine vertraulichen Benachrichtigungen auf dem Sperrbildschirm anzeigen. Die Sicherheitsanforderungen für nicht-tragbare IoT-Geräte (Sensoren, industrielle IoT, Smart-Building-Komponenten) werden in der Netzwerksegmentierung (p16) und ggf. OT-spezifischen Richtlinien behandelt.", descriptionEn: "Wearables (smartwatches, fitness trackers) with organisational access must be covered by the MDM policy. Voice assistants must be disabled in security areas. Wearables must not display confidential notifications on the lock screen. Security requirements for non-wearable IoT devices (sensors, industrial IoT, smart building components) are addressed in network segmentation (p16) and OT-specific policies where applicable.", reason: "Wearables erweitern die Angriffsfläche und haben oft eingeschränkte Sicherheitsfunktionen.", reasonEn: "Wearables expand the attack surface and often have limited security capabilities.", whenRequired: "Erforderlich bei Einsatz von Wearables.", whenRequiredEn: "Required when using wearables.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.4.4"] },
];

// ═══════════════════════════════════════════════════════════════
// P24 — Media Handling & Data Carrier Policy (22 clauses)
// ═══════════════════════════════════════════════════════════════
const p24: PolicyClause[] = [
  { id: "p24-c00", title: "Klassifizierung von Datenträgern", titleEn: "Classification of Data Carriers", description: "Alle Datenträger (USB-Sticks, externe Festplatten, CDs/DVDs, Backup-Bänder, SD-Karten, NAS-Geräte) müssen entsprechend der höchsten Vertraulichkeitsstufe der darauf gespeicherten Daten klassifiziert und gekennzeichnet werden. Die Kennzeichnung muss dauerhaft und eindeutig sein.", descriptionEn: "All data carriers (USB sticks, external hard drives, CDs/DVDs, backup tapes, SD cards, NAS devices) must be classified and labelled according to the highest confidentiality level of data stored on them. Labelling must be permanent and unambiguous.", reason: "Ohne Klassifizierung werden Datenträger nicht entsprechend ihrem Schutzbedarf behandelt.", reasonEn: "Without classification, data carriers are not handled according to their protection needs.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz CON.6", "NIST CSF 2.0 PR.DS-01"] },
  { id: "p24-c01", title: "Zugelassene Datenträger", titleEn: "Approved Data Carriers", description: "Nur von der Organisation genehmigte und verschlüsselte Datenträger dürfen für den Transport von Organisationsdaten verwendet werden. Hardware-verschlüsselte USB-Sticks müssen als Standard bereitgestellt werden. Die Verwendung privater Datenträger für Organisationsdaten ist verboten.", descriptionEn: "Only organisation-approved and encrypted data carriers may be used for transporting organisational data. Hardware-encrypted USB sticks must be provided as standard. Use of private data carriers for organisational data is prohibited.", reason: "Nicht genehmigte Datenträger können unsicher, infiziert oder unverschlüsselt sein.", reasonEn: "Unapproved data carriers can be insecure, infected, or unencrypted.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c02", title: "Verschlüsselung von Datenträgern", titleEn: "Encryption of Data Carriers", description: "Alle transportablen Datenträger, die vertrauliche oder personenbezogene Daten enthalten, müssen verschlüsselt sein. AES-256 ist der Mindeststandard. Hardwareverschlüsselung (FIPS 140-2/3 zertifiziert) muss bevorzugt werden. Die Verschlüsselungsschlüssel müssen getrennt vom Datenträger verwaltet werden.", descriptionEn: "All portable data carriers containing confidential or personal data must be encrypted. AES-256 is the minimum standard. Hardware encryption (FIPS 140-2/3 certified) must be preferred. Encryption keys must be managed separately from the data carrier.", reason: "Ohne Verschlüsselung sind Daten auf verlorenen oder gestohlenen Datenträgern sofort lesbar.", reasonEn: "Without encryption, data on lost or stolen data carriers is immediately readable.", whenRequired: "Immer für vertrauliche Daten.", whenRequiredEn: "Always for confidential data.", sources: ["ISO 27001:2022 A.8.24", "BSI IT-Grundschutz CON.6", "DSGVO Art.32", "NIS2 Art.21(2)(e)"] },
  { id: "p24-c03", title: "Sicherer Transport von Datenträgern", titleEn: "Secure Transport of Data Carriers", description: "Der Transport von Datenträgern mit vertraulichen Daten muss gesichert erfolgen: verschlossene, manipulationssichere Behälter, dokumentierte Übergabe, Empfangsbestätigung, Nachverfolgbarkeit. Für hochvertrauliche Daten muss ein Kurierdienst mit Sicherheitsfreigabe oder verschlüsselter elektronischer Transfer bevorzugt werden.", descriptionEn: "Transport of data carriers with confidential data must be secured: locked, tamper-evident containers, documented handover, acknowledgement of receipt, traceability. For highly confidential data, a security-cleared courier service or encrypted electronic transfer must be preferred.", reason: "Beim Transport sind Datenträger besonders gefährdet durch Verlust, Diebstahl und Manipulation.", reasonEn: "During transport, data carriers are particularly vulnerable to loss, theft, and tampering.", whenRequired: "Erforderlich beim Transport vertraulicher Daten.", whenRequiredEn: "Required when transporting confidential data.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c04", title: "Sichere Vernichtung von Datenträgern", titleEn: "Secure Destruction of Data Carriers", description: "Nicht mehr benötigte Datenträger müssen nach DIN 66399 oder gleichwertigen Standards sicher vernichtet werden. Magnetische Medien: Degaussing und physische Vernichtung. SSDs/Flash: Secure Erase und physische Vernichtung. Papier: Schredder (DIN 66399, Sicherheitsstufe P-4 oder höher). Die Vernichtung muss dokumentiert werden (Vernichtungsprotokoll mit Seriennummer, Datum, Verfahren).", descriptionEn: "Data carriers no longer needed must be securely destroyed according to DIN 66399 or equivalent standards. Magnetic media: degaussing and physical destruction. SSDs/Flash: Secure Erase and physical destruction. Paper: shredder (DIN 66399, security level P-4 or higher). Destruction must be documented (destruction protocol with serial number, date, method).", reason: "Unzureichend vernichtete Datenträger sind eine häufige Quelle für Datenlecks.", reasonEn: "Insufficiently destroyed data carriers are a common source of data leaks.", whenRequired: "Immer bei Entsorgung.", whenRequiredEn: "Always during disposal.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz CON.6", "DIN 66399", "NIST SP 800-88"] },
  { id: "p24-c05", title: "Inventarisierung von Datenträgern", titleEn: "Data Carrier Inventory", description: "Alle transportablen Datenträger, die vertrauliche Daten enthalten oder enthalten können, müssen inventarisiert werden. Das Inventar muss mindestens umfassen: Art des Datenträgers, Seriennummer/ID, Verantwortlicher, Klassifizierung, Standort, Ausgabedatum und Status (aktiv, im Lager, zur Vernichtung).", descriptionEn: "All portable data carriers containing or potentially containing confidential data must be inventoried. The inventory must include at minimum: type of data carrier, serial number/ID, responsible person, classification, location, issue date, and status (active, in storage, for destruction).", reason: "Ohne Inventar ist der Verbleib von Datenträgern und damit der Schutz der darauf gespeicherten Daten nicht nachvollziehbar.", reasonEn: "Without inventory, the whereabouts of data carriers and thus the protection of data stored on them cannot be traced.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c06", title: "Wiederverwendung von Datenträgern", titleEn: "Reuse of Data Carriers", description: "Vor der Wiederverwendung oder Weitergabe von Datenträgern müssen alle vorherigen Daten sicher gelöscht werden. Einfaches Löschen oder Formatieren ist nicht ausreichend — NIST SP 800-88-konforme Löschverfahren müssen angewendet werden. Die erfolgreiche Löschung muss verifiziert und dokumentiert werden.", descriptionEn: "Before reuse or transfer of data carriers, all previous data must be securely erased. Simple deletion or formatting is not sufficient — NIST SP 800-88-compliant erasure procedures must be applied. Successful erasure must be verified and documented.", reason: "Gelöschte Daten können mit forensischen Methoden wiederhergestellt werden, wenn sie nicht sicher überschrieben wurden.", reasonEn: "Deleted data can be recovered using forensic methods if not securely overwritten.", whenRequired: "Immer bei Wiederverwendung.", whenRequiredEn: "Always during reuse.", sources: ["ISO 27001:2022 A.7.14", "NIST SP 800-88", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c07", title: "Datenträger in Wartung und Reparatur", titleEn: "Data Carriers in Maintenance and Repair", description: "Wenn Geräte mit Datenträgern zur Wartung oder Reparatur an Dritte gegeben werden, müssen alle vertraulichen Daten vorher sicher gelöscht oder die Datenträger entfernt werden. Wenn dies nicht möglich ist, müssen vertragliche Vereinbarungen die Vertraulichkeit sicherstellen und der Dienstleister muss überprüft sein.", descriptionEn: "When devices with data carriers are given to third parties for maintenance or repair, all confidential data must be securely erased beforehand or the data carriers must be removed. If this is not possible, contractual agreements must ensure confidentiality and the service provider must be vetted.", reason: "Wartungspersonal hat physischen Zugriff auf Datenträger und kann ohne Schutzmaßnahmen auf Daten zugreifen.", reasonEn: "Maintenance personnel have physical access to data carriers and can access data without protective measures.", whenRequired: "Immer bei externer Wartung.", whenRequiredEn: "Always during external maintenance.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c08", title: "Aufbewahrung von Datenträgern", titleEn: "Storage of Data Carriers", description: "Datenträger mit vertraulichen Daten müssen in gesicherten Bereichen aufbewahrt werden — verschlossene Schränke oder Tresore, je nach Klassifizierung. Backup-Bänder müssen in feuersicheren Tresoren und idealerweise an einem separaten Standort gelagert werden. Umgebungsbedingungen (Temperatur, Feuchtigkeit) müssen den Herstellervorgaben entsprechen.", descriptionEn: "Data carriers with confidential data must be stored in secured areas — locked cabinets or safes, depending on classification. Backup tapes must be stored in fireproof safes and ideally at a separate location. Environmental conditions (temperature, humidity) must comply with manufacturer specifications.", reason: "Unsichere Aufbewahrung setzt Datenträger dem Risiko von Diebstahl, unbefugtem Zugriff und physischer Beschädigung aus.", reasonEn: "Insecure storage exposes data carriers to the risk of theft, unauthorised access, and physical damage.", whenRequired: "Immer für vertrauliche Datenträger.", whenRequiredEn: "Always for confidential data carriers.", sources: ["ISO 27001:2022 A.7.8", "BSI IT-Grundschutz INF.5", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c09", title: "Sichere Druckinfrastruktur und Ausgabemanagement", titleEn: "Secure Print Infrastructure and Output Management", description: "Vertrauliche Druckausgaben müssen durch Pull-Printing (Auslösung am Drucker durch Authentifizierung) geschützt werden. Nicht benötigte Ausdrucke müssen sofort geschreddert werden. Drucker in öffentlich zugänglichen Bereichen dürfen nicht für vertrauliche Dokumente verwendet werden. Druckprotokolle müssen für vertrauliche Dokumente geführt werden. Diese Klausel regelt die technische Druckinfrastruktur (Pull-Printing-Systeme, Druckerstandorte, Protokollierung); die verhaltensbezogene Disziplin beim Abholen und Umgang mit Ausdrucken wird in p25-c06 (Drucker- und Kopierer-Disziplin) geregelt.", descriptionEn: "Confidential print outputs must be protected through pull printing (release at printer via authentication). Unnecessary printouts must be immediately shredded. Printers in publicly accessible areas must not be used for confidential documents. Print logs must be maintained for confidential documents. This clause governs the technical print infrastructure (pull-printing systems, printer locations, logging); behavioural discipline for collecting and handling printouts is governed in p25-c06 (Printer and Copier Discipline).", reason: "Vergessene Ausdrucke an Druckern sind eine häufige und oft unterschätzte Quelle für Informationslecks.", reasonEn: "Forgotten printouts at printers are a frequent and often underestimated source of information leaks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz CON.6", "BSI IT-Grundschutz SYS.4.1"] },
  { id: "p24-c10", title: "Externe Datenträger-Scan", titleEn: "External Data Carrier Scanning", description: "Alle externen Datenträger müssen vor der Verwendung im Organisationsnetzwerk auf Malware gescannt werden. Automatisiertes Scanning beim Anschließen muss konfiguriert sein. Für Hochsicherheitsbereiche muss ein dedizierter Scan-Rechner (Air-Gapped) bereitgestellt werden. Die operativen Malware-Erkennungs- und Reaktionsprozesse (Signatur-Updates, Quarantäne, SOC-Eskalation) werden in p20 (Malware Protection) geregelt; diese Klausel fokussiert auf die Scan-Pflicht speziell für physische Datenträger vor Netzwerkzugang.", descriptionEn: "All external data carriers must be scanned for malware before use in the organisational network. Automated scanning upon connection must be configured. For high-security areas, a dedicated scanning computer (air-gapped) must be provided. Operational malware detection and response processes (signature updates, quarantine, SOC escalation) are governed in p20 (Malware Protection); this clause focuses on the scanning obligation specifically for physical data carriers before network access.", reason: "Externe Datenträger sind ein verbreiteter Vektor für Malware-Einschleusung.", reasonEn: "External data carriers are a common vector for malware injection.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4"] },
  { id: "p24-c11", title: "Cloud-Transfer statt physische Medien", titleEn: "Cloud Transfer Instead of Physical Media", description: "Wir müssen sichere elektronische Transfermethoden (verschlüsselte Cloud-Speicher, SFTP, sichere Filesharing-Dienste) gegenüber physischen Datenträgern bevorzugen. Physische Datenträger sollten nur verwendet werden, wenn elektronischer Transfer nicht möglich oder nicht praktikabel ist.", descriptionEn: "We must prefer secure electronic transfer methods (encrypted cloud storage, SFTP, secure file sharing services) over physical data carriers. Physical data carriers should only be used when electronic transfer is not possible or practical.", reason: "Elektronischer Transfer eliminiert die physischen Risiken von Datenträgern (Verlust, Diebstahl, Beschädigung).", reasonEn: "Electronic transfer eliminates the physical risks of data carriers (loss, theft, damage).", whenRequired: "Empfohlen.", whenRequiredEn: "Recommended.", sources: ["ISO 27001:2022 A.8.24", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c12", title: "Datenträger-Handling durch Dritte", titleEn: "Data Carrier Handling by Third Parties", description: "Wenn Dritte mit der Handhabung, dem Transport oder der Vernichtung von Datenträgern beauftragt werden, müssen vertragliche Vereinbarungen die Sicherheitsanforderungen festlegen. Vernichtungsunternehmen müssen zertifiziert sein (z.B. nach DIN 66399). Dokumentation und Nachweise müssen eingeholt und archiviert werden. Die übergeordneten Anforderungen an Lieferantenbewertung, vertragliche Sicherheitsklauseln und laufendes Lieferantenmonitoring werden in p42 (Supplier Security Assessment) und p43 (Supplier Monitoring) geregelt; diese Klausel fokussiert auf die spezifischen Anforderungen an Dritte, die physische Datenträger handhaben.", descriptionEn: "When third parties are commissioned with handling, transporting, or destroying data carriers, contractual agreements must specify security requirements. Destruction companies must be certified (e.g., per DIN 66399). Documentation and evidence must be obtained and archived. Overarching requirements for supplier evaluation, contractual security clauses, and ongoing supplier monitoring are governed in p42 (Supplier Security Assessment) and p43 (Supplier Monitoring); this clause focuses on specific requirements for third parties handling physical data carriers.", reason: "Dritte, die mit Datenträgern umgehen, müssen vertraglich an dieselben Sicherheitsstandards gebunden sein.", reasonEn: "Third parties handling data carriers must be contractually bound to the same security standards.", whenRequired: "Erforderlich bei Beauftragung Dritter.", whenRequiredEn: "Required when commissioning third parties.", sources: ["ISO 27001:2022 A.5.20", "BSI IT-Grundschutz CON.6", "DIN 66399"] },
  { id: "p24-c13", title: "Archivierungs-Datenträger", titleEn: "Archival Data Carriers", description: "Für die Langzeitarchivierung verwendete Datenträger müssen hinsichtlich ihrer Haltbarkeit, Lesbarkeit und Technologieverfügbarkeit überwacht werden. Regelmäßige Lesbarkeits-Tests müssen durchgeführt werden. Daten müssen rechtzeitig auf aktuelle Medien migriert werden, bevor die Technologie obsolet wird.", descriptionEn: "Data carriers used for long-term archiving must be monitored regarding their durability, readability, and technology availability. Regular readability tests must be conducted. Data must be migrated to current media in time before the technology becomes obsolete.", reason: "Archivdaten können unlesbar werden, wenn Medien degradieren oder Lesegeräte nicht mehr verfügbar sind.", reasonEn: "Archive data can become unreadable when media degrades or readers are no longer available.", whenRequired: "Erforderlich bei Langzeitarchivierung.", whenRequiredEn: "Required for long-term archiving.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c14", title: "DLP für Datenträger", titleEn: "DLP for Data Carriers", description: "Data Loss Prevention (DLP) Mechanismen müssen das Kopieren vertraulicher Daten auf nicht autorisierte Datenträger verhindern. DLP-Regeln müssen die Klassifizierung der Daten berücksichtigen und nur genehmigte Transfers auf genehmigte, verschlüsselte Datenträger erlauben. Verstöße müssen protokolliert und gemeldet werden.", descriptionEn: "Data Loss Prevention (DLP) mechanisms must prevent copying of confidential data to unauthorised data carriers. DLP rules must consider data classification and only allow approved transfers to approved, encrypted data carriers. Violations must be logged and reported.", reason: "DLP verhindert unbeabsichtigten oder absichtlichen Datenabfluss über Datenträger.", reasonEn: "DLP prevents unintentional or intentional data exfiltration via data carriers.", whenRequired: "Empfohlen für alle, erforderlich für hochvertrauliche Daten.", whenRequiredEn: "Recommended for all, required for highly confidential data.", sources: ["ISO 27001:2022 A.8.12", "BSI IT-Grundschutz CON.6", "CIS Controls v8 3.1"] },
  { id: "p24-c15", title: "Medienspezifisches Sicherheitsbriefing", titleEn: "Media-Specific Security Briefing", description: "Alle Beschäftigten, die regelmäßig mit physischen Datenträgern umgehen, müssen ein medienspezifisches Sicherheitsbriefing erhalten. Das Briefing muss die praktische Anwendung dieser Richtlinie abdecken: Klassifizierung, Verschlüsselung, Transport, Aufbewahrung, Vernichtung und Meldepflichten bei Verlust. Dieses Briefing ergänzt die allgemeinen Sicherheitsschulungen, die in p44 (Security Awareness Programme) und p45 (Role-Based Security Training) zentral geregelt werden; hier werden nur die medienspezifischen Handlungsanweisungen vermittelt.", descriptionEn: "All employees who regularly handle physical data carriers must receive a media-specific security briefing. The briefing must cover practical application of this policy: classification, encryption, transport, storage, destruction, and reporting obligations for loss. This briefing supplements the general security training centrally governed in p44 (Security Awareness Programme) and p45 (Role-Based Security Training); only media-specific operational instructions are covered here.", reason: "Medienspezifische Risiken erfordern praxisnahe Handlungsanweisungen über die allgemeine Awareness hinaus.", reasonEn: "Media-specific risks require practical operational instructions beyond general awareness.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3"] },
  { id: "p24-c16", title: "Datenträger-Austausch mit externen Partnern", titleEn: "Data Carrier Exchange with External Partners", description: "Der Austausch von Datenträgern mit externen Partnern muss durch Vereinbarungen geregelt werden, die Verschlüsselungsanforderungen, Transportverfahren, Vernichtungspflichten und Vertraulichkeitsvereinbarungen festlegen. Empfangene Datenträger müssen vor der Verwendung auf Malware gescannt werden.", descriptionEn: "Exchange of data carriers with external partners must be governed by agreements specifying encryption requirements, transport procedures, destruction obligations, and confidentiality agreements. Received data carriers must be scanned for malware before use.", reason: "Ohne Vereinbarungen besteht keine Kontrolle über den Umgang externer Partner mit den ausgetauschten Daten.", reasonEn: "Without agreements, there is no control over external partners' handling of exchanged data.", whenRequired: "Erforderlich bei externem Austausch.", whenRequiredEn: "Required for external exchange.", sources: ["ISO 27001:2022 A.5.14", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c17", title: "Datenträger in Druckern und Multifunktionsgeräten", titleEn: "Data Carriers in Printers and Multifunction Devices", description: "Die internen Speicher von Druckern, Multifunktionsgeräten und Kopierern müssen als Datenträger behandelt werden. Automatische Löschung nach dem Druckvorgang muss konfiguriert sein. Bei Außerbetriebnahme oder Rückgabe müssen die internen Speicher sicher gelöscht werden. Festplatten in Druckern müssen verschlüsselt sein.", descriptionEn: "Internal storage of printers, multifunction devices, and copiers must be treated as data carriers. Automatic deletion after printing must be configured. During decommissioning or return, internal storage must be securely erased. Hard drives in printers must be encrypted.", reason: "Drucker und Multifunktionsgeräte speichern häufig Kopien aller verarbeiteten Dokumente auf internen Festplatten.", reasonEn: "Printers and multifunction devices frequently store copies of all processed documents on internal hard drives.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz SYS.4.1"] },
  { id: "p24-c18", title: "Medien-Handling-Protokollierung", titleEn: "Media Handling Logging", description: "Die Ausgabe, der Transport, die Rückgabe und die Vernichtung von Datenträgern mit vertraulichen Daten müssen protokolliert werden. Das Protokoll muss umfassen: Datum, Datenträger-ID, Handelnde Person, Empfänger, Zweck und bestätigter Empfang/Vernichtung.", descriptionEn: "Issuance, transport, return, and destruction of data carriers with confidential data must be logged. The log must include: date, data carrier ID, acting person, recipient, purpose, and confirmed receipt/destruction.", reason: "Lückenlose Protokollierung ist Voraussetzung für die Nachvollziehbarkeit des Verbleibs vertraulicher Datenträger.", reasonEn: "Complete logging is a prerequisite for traceability of confidential data carriers.", whenRequired: "Erforderlich für vertrauliche Datenträger.", whenRequiredEn: "Required for confidential data carriers.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c19", title: "Notfallvernichtung von Datenträgern", titleEn: "Emergency Destruction of Data Carriers", description: "Wir müssen ein Verfahren für die Notfallvernichtung von Datenträgern definieren — z.B. bei Evakuierung, feindlicher Übernahme oder bei Gefahr des unbefugten Zugriffs auf hochvertrauliche Daten. Notfallvernichtungsmittel (Schredder, Entmagnetisierer) müssen an kritischen Standorten verfügbar sein.", descriptionEn: "We must define a procedure for emergency destruction of data carriers — e.g., during evacuation, hostile takeover, or when there is danger of unauthorised access to highly confidential data. Emergency destruction means (shredders, degaussers) must be available at critical locations.", reason: "In Extremsituationen muss die sofortige Vernichtung vertraulicher Datenträger möglich sein.", reasonEn: "In extreme situations, immediate destruction of confidential data carriers must be possible.", whenRequired: "Erforderlich für hochvertrauliche Umgebungen.", whenRequiredEn: "Required for highly confidential environments.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c20", title: "Datenträger-Risikobewertung", titleEn: "Data Carrier Risk Assessment", description: "Wir müssen regelmäßig eine Risikobewertung für die Nutzung von Datenträgern durchführen. Die Bewertung muss Bedrohungen wie Verlust, Diebstahl, Malware-Einschleusung und unbefugte Datenkopien berücksichtigen. Ergebnisse müssen in die Datenträgerrichtlinie einfließen.", descriptionEn: "We must regularly conduct a risk assessment for data carrier usage. The assessment must consider threats such as loss, theft, malware injection, and unauthorised data copying. Results must feed into the data carrier policy.", reason: "Ohne Risikobewertung werden Datenträgerrisiken nicht systematisch adressiert.", reasonEn: "Without risk assessment, data carrier risks are not systematically addressed.", whenRequired: "Mindestens jährlich.", whenRequiredEn: "At least annually.", sources: ["ISO 27001:2022 §6.1.2", "BSI IT-Grundschutz CON.6"] },
  { id: "p24-c21", title: "Überprüfung der Datenträger-Richtlinie", titleEn: "Review of Data Carrier Policy", description: "Diese Richtlinie muss mindestens jährlich überprüft und aktualisiert werden. Neue Technologien, Bedrohungen und regulatorische Anforderungen müssen berücksichtigt werden.", descriptionEn: "This policy must be reviewed and updated at least annually. New technologies, threats, and regulatory requirements must be considered.", reason: "Datenträger-Technologien und Bedrohungen entwickeln sich ständig weiter.", reasonEn: "Data carrier technologies and threats are constantly evolving.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz CON.6"] },
];

// ═══════════════════════════════════════════════════════════════
// P25 — Clean Desk & Clear Screen Policy (22 clauses)
// ═══════════════════════════════════════════════════════════════
const p25: PolicyClause[] = [
  { id: "p25-c00", title: "Clean-Desk-Grundsatz", titleEn: "Clean Desk Principle", description: "Alle Beschäftigten müssen ihren Arbeitsplatz bei Verlassen — auch bei kurzer Abwesenheit während der Arbeitszeit — so hinterlassen, dass keine vertraulichen Informationen offen sichtbar oder zugänglich sind. Dokumente, Datenträger und Notizen müssen in verschließbaren Schränken oder Schubladen aufbewahrt werden. Am Arbeitsende müssen alle Unterlagen vollständig verstaut werden.", descriptionEn: "All employees must leave their workspace when departing — even during brief absences during working hours — so that no confidential information is openly visible or accessible. Documents, data carriers, and notes must be stored in lockable cabinets or drawers. At the end of the workday, all materials must be fully stowed.", reason: "Offenliegende vertrauliche Dokumente können von unbefugten Personen (Besucher, Reinigungspersonal, Mitarbeiter ohne Need-to-Know) eingesehen werden.", reasonEn: "Exposed confidential documents can be viewed by unauthorised persons (visitors, cleaning staff, employees without need-to-know).", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7", "NIS2 Art.21(2)(i)"] },
  { id: "p25-c01", title: "Clear-Screen-Grundsatz", titleEn: "Clear Screen Principle", description: "Computerbildschirme müssen beim Verlassen des Arbeitsplatzes gesperrt werden — auch bei kurzer Abwesenheit. Die automatische Bildschirmsperre muss nach maximal 10 Minuten Inaktivität aktiviert werden (5 Minuten für Geräte in öffentlich zugänglichen Bereichen). Tastenkombinationen zum manuellen Sperren (Win+L, Ctrl+Cmd+Q) müssen allen Beschäftigten bekannt sein.", descriptionEn: "Computer screens must be locked when leaving the workspace — even during brief absence. Automatic screen lock must activate after maximum 10 minutes of inactivity (5 minutes for devices in publicly accessible areas). Keyboard shortcuts for manual locking (Win+L, Ctrl+Cmd+Q) must be known to all employees.", reason: "Ein ungesperrter Bildschirm ermöglicht unbefugten Zugriff auf Systeme und Daten mit den Berechtigungen des angemeldeten Benutzers.", reasonEn: "An unlocked screen enables unauthorised access to systems and data with the permissions of the logged-in user.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 4.3"] },
  { id: "p25-c02", title: "Verschließbare Aufbewahrung", titleEn: "Lockable Storage", description: "Wir müssen jedem Beschäftigten ausreichende verschließbare Aufbewahrungsmöglichkeiten bereitstellen — Schränke, Schubladen, Rollcontainer. Schlüssel und Zugangscodes dürfen nicht an unbefugte Personen weitergegeben werden. Bei Verlust von Schlüsseln muss das Schloss umgehend getauscht werden.", descriptionEn: "We must provide each employee with sufficient lockable storage — cabinets, drawers, pedestal units. Keys and access codes must not be shared with unauthorised persons. In case of key loss, the lock must be changed immediately.", reason: "Clean Desk ist nur umsetzbar, wenn angemessene sichere Aufbewahrungsmöglichkeiten zur Verfügung stehen.", reasonEn: "Clean desk is only feasible when adequate secure storage options are available.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c03", title: "Sichere Entsorgung am Arbeitsplatz", titleEn: "Secure Disposal at Workstations", description: "An jedem Arbeitsbereich müssen Sicherheitsabfallbehälter (Vertraulichkeitsbehälter) für die sichere Entsorgung vertraulicher Dokumente bereitgestellt werden. Papierkorb darf nicht für vertrauliche Dokumente verwendet werden. Die Leerung der Vertraulichkeitsbehälter muss durch zertifiziertes Personal oder zertifizierte Dienstleister erfolgen.", descriptionEn: "Secure waste containers (confidential waste bins) must be provided at each work area for secure disposal of confidential documents. Regular waste bins must not be used for confidential documents. Emptying of confidential waste bins must be performed by certified personnel or certified service providers.", reason: "Ohne sichere Entsorgungsmöglichkeiten am Arbeitsplatz werden vertrauliche Dokumente im normalen Papierkorb entsorgt.", reasonEn: "Without secure disposal options at workstations, confidential documents are disposed of in regular waste bins.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz INF.7", "DIN 66399"] },
  { id: "p25-c04", title: "Whiteboard- und Flipchart-Reinigung", titleEn: "Whiteboard and Flipchart Clearing", description: "Whiteboards und Flipcharts in Besprechungsräumen müssen nach vertraulichen Besprechungen gereinigt bzw. Blätter entfernt werden. Vertrauliche Inhalte dürfen nicht auf Whiteboards sichtbar bleiben. Gebrauchte Flipchart-Blätter mit vertraulichem Inhalt müssen sicher entsorgt werden.", descriptionEn: "Whiteboards and flipcharts in meeting rooms must be cleaned or sheets removed after confidential meetings. Confidential content must not remain visible on whiteboards. Used flipchart sheets with confidential content must be securely disposed of.", reason: "Sichtbare Notizen aus vertraulichen Besprechungen können von nachfolgenden Raumnutzern eingesehen werden.", reasonEn: "Visible notes from confidential meetings can be viewed by subsequent room users.", whenRequired: "Immer nach vertraulichen Besprechungen.", whenRequiredEn: "Always after confidential meetings.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c05", title: "Sichtschutz und Blickschutzfolien", titleEn: "Privacy Screens and Filters", description: "Für Geräte, die in öffentlich zugänglichen Bereichen, Großraumbüros oder bei der Arbeit unterwegs verwendet werden, müssen Blickschutzfolien (Privacy Filter) bereitgestellt und verwendet werden. Bildschirme müssen so positioniert werden, dass der Inhalt nicht von Besuchern oder unbefugten Personen einsehbar ist.", descriptionEn: "For devices used in publicly accessible areas, open-plan offices, or when working on the go, privacy filters must be provided and used. Screens must be positioned so content is not viewable by visitors or unauthorised persons.", reason: "Visual Hacking (Abschauen von Bildschirminhalten) ist ein unterschätzter aber wirksamer Angriffsvektor.", reasonEn: "Visual hacking (viewing screen contents) is an underestimated but effective attack vector.", whenRequired: "Erforderlich in öffentlichen und Großraum-Bereichen.", whenRequiredEn: "Required in public and open-plan areas.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c06", title: "Drucker- und Kopierer-Disziplin", titleEn: "Printer and Copier Discipline", description: "Ausdrucke müssen sofort nach dem Druck abgeholt werden. Pull-Printing (Secure Printing) muss für alle vertraulichen Dokumente verwendet werden. Vergessene Ausdrucke müssen vom Reinigungspersonal oder IT-Support sicher vernichtet werden. Scan-Ziele müssen nur autorisierte E-Mail-Adressen oder Netzwerkordner sein. Diese Klausel regelt das verhaltensbezogene Abholen, den Umgang und die sichere Entsorgung von Ausdrucken; die technische Druckinfrastruktur (Pull-Printing-Systeme, Druckerstandorte, Druckprotokolle, Druckerfestplatten-Verschlüsselung) wird in p24-c09 (Sichere Druckinfrastruktur) und p24-c17 (Datenträger in Druckern) geregelt.", descriptionEn: "Printouts must be collected immediately after printing. Pull printing (secure printing) must be used for all confidential documents. Forgotten printouts must be securely destroyed by cleaning staff or IT support. Scan destinations must only be authorised email addresses or network folders. This clause governs behavioural collection, handling, and secure disposal of printouts; technical print infrastructure (pull-printing systems, printer locations, print logs, printer hard drive encryption) is governed in p24-c09 (Secure Print Infrastructure) and p24-c17 (Data Carriers in Printers).", reason: "Vergessene Ausdrucke am Drucker sind eine der häufigsten Ursachen für Informationslecks in Büroumgebungen.", reasonEn: "Forgotten printouts at printers are one of the most common causes of information leaks in office environments.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz SYS.4.1"] },
  { id: "p25-c07", title: "Besprechungsräume und Shared Spaces", titleEn: "Meeting Rooms and Shared Spaces", description: "In Besprechungsräumen und gemeinsam genutzten Arbeitsbereichen müssen alle Materialien nach der Nutzung entfernt werden. Vertrauliche Dokumente dürfen nicht in Besprechungsräumen zurückgelassen werden. Screensharing-Sessions müssen beendet und Bildschirme gesperrt werden. USB-Geräte und Notizen müssen mitgenommen werden.", descriptionEn: "In meeting rooms and shared workspaces, all materials must be removed after use. Confidential documents must not be left behind in meeting rooms. Screen sharing sessions must be ended and screens locked. USB devices and notes must be taken along.", reason: "Gemeinsam genutzte Räume werden von verschiedenen Personengruppen verwendet, einschließlich potenziell unbefugter Besucher.", reasonEn: "Shared spaces are used by different groups of people, including potentially unauthorised visitors.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c08", title: "Home-Office Clean Desk", titleEn: "Home Office Clean Desk", description: "Clean-Desk- und Clear-Screen-Anforderungen gelten auch für Heimarbeitsplätze. Vertrauliche Dokumente müssen in verschließbaren Möbeln aufbewahrt werden. Der Arbeitsbereich muss von anderen Haushaltsmitgliedern nicht einsehbar sein. Vertrauliche Telefonate müssen in geschlossenen Räumen geführt werden. Sichere Entsorgungsmöglichkeiten müssen am Heimarbeitsplatz vorhanden sein.", descriptionEn: "Clean desk and clear screen requirements also apply to home workplaces. Confidential documents must be stored in lockable furniture. The work area must not be viewable by other household members. Confidential phone calls must be conducted in closed rooms. Secure disposal options must be available at the home workplace.", reason: "Im Home-Office ist die physische Sicherheit geringer als im Büro, da andere Haushaltsmitglieder oder Besucher Zugang haben.", reasonEn: "In the home office, physical security is lower than in the office, as other household members or visitors have access.", whenRequired: "Erforderlich bei Heimarbeit.", whenRequiredEn: "Required for home work.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz INF.9"] },
  { id: "p25-c09", title: "Fotografier- und Aufnahmeverbot", titleEn: "Photography and Recording Prohibition", description: "Das Fotografieren oder Filmen von Bildschirminhalten, vertraulichen Dokumenten oder Sicherheitseinrichtungen muss in Sicherheitsbereichen verboten sein. Besucher müssen auf das Fotografierverbot hingewiesen werden. Smartphones dürfen in Hochsicherheitsbereichen nicht verwendet werden oder müssen abgegeben werden.", descriptionEn: "Photographing or filming of screen contents, confidential documents, or security facilities must be prohibited in security areas. Visitors must be informed of the photography ban. Smartphones must not be used in high-security areas or must be surrendered.", reason: "Fotografien von Bildschirmen und Dokumenten umgehen alle digitalen Schutzmaßnahmen.", reasonEn: "Photographs of screens and documents bypass all digital security measures.", whenRequired: "Erforderlich in Sicherheitsbereichen.", whenRequiredEn: "Required in security areas.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c10", title: "Notizbücher und physische Notizen", titleEn: "Notebooks and Physical Notes", description: "Physische Notizbücher und Haftnotizen (Post-its) mit vertraulichen Informationen müssen wie vertrauliche Dokumente behandelt werden. Haftnotizen mit Passwörtern, Zugangscodes oder vertraulichen Informationen am Monitor oder Schreibtisch sind strikt verboten. Notizbücher mit vertraulichem Inhalt müssen verschlossen aufbewahrt werden.", descriptionEn: "Physical notebooks and sticky notes (post-its) with confidential information must be treated as confidential documents. Sticky notes with passwords, access codes, or confidential information on monitors or desks are strictly prohibited. Notebooks with confidential content must be stored locked.", reason: "Handschriftliche Notizen mit Passwörtern oder sensiblen Daten sind ein trivial ausnutzbarer Sicherheitsverstoß.", reasonEn: "Handwritten notes with passwords or sensitive data are a trivially exploitable security violation.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c11", title: "Stichprobenprüfungen und Walk-Throughs", titleEn: "Spot Checks and Walk-Throughs", description: "Wir müssen regelmäßige Stichprobenprüfungen (Walk-Throughs) durchführen, um die Einhaltung der Clean-Desk- und Clear-Screen-Richtlinie zu überprüfen. Prüfungen müssen unangekündigt und zu verschiedenen Tageszeiten stattfinden. Ergebnisse müssen dokumentiert und Verstöße nachverfolgt werden. Bei wiederholten Verstößen müssen disziplinarische Maßnahmen eingeleitet werden.", descriptionEn: "We must conduct regular spot checks (walk-throughs) to verify compliance with the clean desk and clear screen policy. Checks must be unannounced and at various times of day. Results must be documented and violations tracked. Disciplinary measures must be initiated for repeated violations.", reason: "Ohne Kontrolle bleibt die Einhaltung der Richtlinie freiwillig und nimmt erfahrungsgemäß schnell ab.", reasonEn: "Without monitoring, compliance with the policy remains voluntary and empirically declines quickly.", whenRequired: "Mindestens vierteljährlich.", whenRequiredEn: "At least quarterly.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c12", title: "Visuelle Informationssicherheit bei Besuchern", titleEn: "Visual Information Security for Visitors", description: "Vor dem Eintreffen von Besuchern müssen vertrauliche Dokumente und Bildschirme gesichert werden. Mitarbeiter müssen darauf hingewiesen werden, wenn Besucher im Bürobereich sind. Transparente Meeting-Räume müssen bei vertraulichen Besprechungen mit Sichtschutz versehen werden. Diese Klausel regelt den Schutz vor visueller Informationsexposition gegenüber Besuchern; die physische Begleitung, Zugangskontrollen und das Besuchermanagement werden in p25-c20 (Besucher und Dritte) geregelt.", descriptionEn: "Before visitor arrival, confidential documents and screens must be secured. Employees must be notified when visitors are in the office area. Transparent meeting rooms must be fitted with privacy screens during confidential meetings. This clause governs protection against visual information exposure to visitors; physical escorting, access controls, and visitor management are governed in p25-c20 (Visitors and Third Parties).", reason: "Besucher haben kein Need-to-Know für interne Informationen und dürfen diese nicht einsehen können.", reasonEn: "Visitors have no need-to-know for internal information and must not be able to view it.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.2", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c13", title: "Abschlussroutine am Arbeitsende", titleEn: "End-of-Day Routine", description: "Alle Beschäftigten müssen am Ende des Arbeitstages eine definierte Abschlussroutine durchführen: Computer herunterfahren oder sperren, alle Dokumente und Datenträger sicher verstauen, vertrauliche Dokumente in Sicherheitsbehälter oder verschlossene Schränke einschließen, Schreibtisch aufräumen. Checklisten können als Hilfe bereitgestellt werden.", descriptionEn: "All employees must perform a defined end-of-day routine: shut down or lock computer, securely store all documents and data carriers, lock confidential documents in security containers or locked cabinets, tidy desk. Checklists can be provided as aids.", reason: "Eine strukturierte Abschlussroutine stellt die konsistente Einhaltung der Clean-Desk-Richtlinie sicher.", reasonEn: "A structured end-of-day routine ensures consistent compliance with the clean desk policy.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c14", title: "Clean-Desk-spezifische Sensibilisierung", titleEn: "Clean-Desk-Specific Awareness", description: "Alle Beschäftigten müssen zur Clean-Desk- und Clear-Screen-Richtlinie sensibilisiert werden — durch Plakate, Erinnerungen an Arbeitsplätzen und Druckern, sowie praktische Beispiele und die Begründung der Regeln. Diese Sensibilisierungsmaßnahmen ergänzen die allgemeinen Sicherheitsschulungen, die in p44 (Security Awareness Programme) und p45 (Role-Based Security Training) zentral geregelt werden; hier werden nur Clean-Desk-spezifische Hinweise und Erinnerungen definiert.", descriptionEn: "All employees must be made aware of the clean desk and clear screen policy — through posters, reminders at workplaces and printers, as well as practical examples and rationale behind the rules. These awareness measures supplement the general security training centrally governed in p44 (Security Awareness Programme) and p45 (Role-Based Security Training); only clean-desk-specific reminders and cues are defined here.", reason: "Clean Desk funktioniert nur, wenn alle Beschäftigten die Regeln kennen, verstehen und akzeptieren.", reasonEn: "Clean desk only works when all employees know, understand, and accept the rules.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3"] },
  { id: "p25-c15", title: "Digitale Clean-Desk-Erweiterung", titleEn: "Digital Clean Desk Extension", description: "Das Clean-Desk-Prinzip muss auch digital angewendet werden: Desktop-Bildschirm muss aufgeräumt sein (keine vertraulichen Dateien auf dem Desktop), temporäre Dateien müssen regelmäßig gelöscht werden, Download-Ordner muss aufgeräumt werden, Browser-Tabs mit vertraulichen Inhalten müssen geschlossen werden.", descriptionEn: "The clean desk principle must also be applied digitally: desktop screen must be tidy (no confidential files on the desktop), temporary files must be regularly deleted, download folders must be tidied, browser tabs with confidential content must be closed.", reason: "Digitaler Unordnung kann ebenso zu Informationslecks führen wie physische Unordnung.", reasonEn: "Digital clutter can lead to information leaks just as physical clutter can.", whenRequired: "Empfohlen.", whenRequiredEn: "Recommended.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c16", title: "Sprachassistenten und Smart Devices am Arbeitsplatz", titleEn: "Voice Assistants and Smart Devices at the Workplace", description: "Sprachassistenten (Alexa, Siri, Google Assistant, Cortana) müssen in Arbeitsbereichen, in denen vertrauliche Gespräche geführt werden, deaktiviert werden. Smart Speaker und IoT-Geräte mit Mikrofonen dürfen nicht in Sicherheitsbereichen betrieben werden. Die Always-On-Listening-Funktion muss deaktiviert werden. Die Sicherheitsanforderungen für tragbare Smart Devices (Smartwatches, Fitness-Tracker) werden in p23-c21 (Wearable-Geräte-Sicherheit) geregelt; diese Klausel fokussiert auf stationäre Sprachassistenten und Smart Devices in Büro- und Besprechungsräumen.", descriptionEn: "Voice assistants (Alexa, Siri, Google Assistant, Cortana) must be disabled in work areas where confidential conversations take place. Smart speakers and IoT devices with microphones must not be operated in security areas. The always-on listening function must be disabled. Security requirements for wearable smart devices (smartwatches, fitness trackers) are governed in p23-c21 (Wearable Device Security); this clause focuses on stationary voice assistants and smart devices in office and meeting rooms.", reason: "Sprachassistenten können vertrauliche Gespräche aufzeichnen und an Cloud-Dienste übertragen.", reasonEn: "Voice assistants can record confidential conversations and transmit them to cloud services.", whenRequired: "Erforderlich in vertraulichen Bereichen.", whenRequiredEn: "Required in confidential areas.", sources: ["ISO 27001:2022 A.7.7", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c17", title: "Kabelmanagement", titleEn: "Cable Management", description: "Arbeitsplätze müssen über ordentliches Kabelmanagement verfügen, um unbeabsichtigtes Ziehen an Kabeln zu verhindern und die physische Sicherheit von Geräten zu gewährleisten. Laptop-Sicherheitskabel (Kensington Lock oder vergleichbar) müssen für Geräte in öffentlich zugänglichen Bereichen bereitgestellt werden.", descriptionEn: "Workplaces must have proper cable management to prevent accidental cable pulling and ensure physical security of devices. Laptop security cables (Kensington Lock or comparable) must be provided for devices in publicly accessible areas.", reason: "Ungesicherte Geräte und unordentliche Kabel erhöhen das Risiko von Diebstahl und Beschädigung.", reasonEn: "Unsecured devices and untidy cables increase the risk of theft and damage.", whenRequired: "Erforderlich in öffentlich zugänglichen Bereichen.", whenRequiredEn: "Required in publicly accessible areas.", sources: ["ISO 27001:2022 A.7.8", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c18", title: "Clean-Desk-Compliance-Monitoring", titleEn: "Clean Desk Compliance Monitoring", description: "Die Einhaltung der Clean-Desk-Richtlinie muss als Teil der Sicherheitskultur gemessen werden. Compliance-Raten müssen als KPI verfolgt werden. Ergebnisse der Walk-Throughs müssen anonymisiert aggregiert und dem Management berichtet werden. Positive Beispiele sollen hervorgehoben werden, um die Compliance-Kultur zu fördern.", descriptionEn: "Compliance with the clean desk policy must be measured as part of security culture. Compliance rates must be tracked as KPIs. Walk-through results must be anonymously aggregated and reported to management. Positive examples should be highlighted to promote compliance culture.", reason: "Was nicht gemessen wird, kann nicht verbessert werden — Compliance-Monitoring macht Clean Desk zum Teil der gelebten Sicherheitskultur.", reasonEn: "What is not measured cannot be improved — compliance monitoring makes clean desk part of the lived security culture.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "BSI IT-Grundschutz INF.7"] },
  { id: "p25-c19", title: "Konsequenzen bei Verstößen", titleEn: "Consequences for Violations", description: "Die Konsequenzen bei wiederholten Verstößen gegen die Clean-Desk- und Clear-Screen-Richtlinie müssen definiert und kommuniziert werden. Erstverstoß: Hinweis und Schulung; wiederholter Verstoß: formelle Abmahnung; schwerwiegender oder vorsätzlicher Verstoß: disziplinarische Maßnahmen gemäß Arbeitsrecht. Die Konsequenzen müssen verhältnismäßig und konsistent angewendet werden.", descriptionEn: "Consequences for repeated violations of the clean desk and clear screen policy must be defined and communicated. First violation: notice and training; repeated violation: formal warning; serious or intentional violation: disciplinary measures per employment law. Consequences must be applied proportionally and consistently.", reason: "Ohne Konsequenzen fehlt die Durchsetzungskraft der Richtlinie.", reasonEn: "Without consequences, the policy lacks enforcement power.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.6.4", "BSI IT-Grundschutz ORP.2"] },
  { id: "p25-c20", title: "Physische Besucherbegleitung und Zutrittskontrolle", titleEn: "Physical Visitor Escort and Access Control", description: "Besucher und externe Dienstleister müssen bei Anwesenheit in Büroräumen physisch begleitet werden. Der Zutritt zu Sicherheitsbereichen muss durch Besucherausweise und Begleitpflicht kontrolliert werden. Besprechungsräume müssen nach Meetings auf zurückgelassene Materialien kontrolliert und aufgeräumt werden. Der visuelle Schutz vertraulicher Informationen vor Besuchern wird in p25-c12 (Visuelle Informationssicherheit) geregelt; diese Klausel fokussiert auf die physische Zutritts- und Begleitkontrolle.", descriptionEn: "Visitors and external service providers must be physically accompanied in office areas. Access to security areas must be controlled through visitor badges and escort requirements. Meeting rooms must be checked for left-behind materials and cleared after meetings. Visual protection of confidential information from visitors is governed in p25-c12 (Visual Information Security); this clause focuses on physical access and escort control.", reason: "Unbegleitete Besucher können physischen Zugang zu vertraulichen Bereichen und Geräten erlangen.", reasonEn: "Unescorted visitors can gain physical access to confidential areas and devices.", whenRequired: "Erforderlich für alle Bereiche mit Besucherzugang.", whenRequiredEn: "Required for all areas with visitor access.", sources: ["ISO 27001:2022 A.7.2, A.7.6", "BSI IT-Grundschutz INF.1"] },
  { id: "p25-c21", title: "Überprüfung der Clean-Desk-Richtlinie", titleEn: "Review of Clean Desk Policy", description: "Diese Richtlinie muss mindestens jährlich überprüft werden. Ergebnisse von Begehungen und Audits müssen einfließen. Neue Arbeitsmodelle (z.B. Desk-Sharing) müssen berücksichtigt werden.", descriptionEn: "This policy must be reviewed at least annually. Results from inspections and audits must feed in. New work models (e.g., hot-desking) must be considered.", reason: "Arbeitsumgebungen und Arbeitsmodelle ändern sich.", reasonEn: "Work environments and models change.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz INF.1"] },
];

export const deviceMediaClauses = { p23, p24, p25 };
